package io.nebulaflow.outbox;
import com.fasterxml.jackson.databind.ObjectMapper; import org.slf4j.*; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.util.Map;
@Component public class OutboxPublisher {private static final Logger log=LoggerFactory.getLogger(OutboxPublisher.class);private final OutboxEventRepository repository;private final KafkaTemplate<String,Object> kafka;private final ObjectMapper mapper;public OutboxPublisher(OutboxEventRepository r,KafkaTemplate<String,Object> k,ObjectMapper m){repository=r;kafka=k;mapper=m;}@Scheduled(fixedDelayString="${nebulaflow.outbox.poll-delay:1000}") public void drain(){for(var event:repository.findTop100ByPublishedAtIsNullOrderByCreatedAtAsc()){try{Map<String,Object> payload=mapper.readValue(event.getPayload(),Map.class);kafka.send(event.getTopic(),event.getEventKey(),payload).whenComplete((result,error)->{if(error==null){event.markPublished();repository.save(event);}else log.warn("outbox delivery failed for {}: {}",event.getId(),error.getMessage());});}catch(Exception e){log.warn("invalid outbox event {}: {}",event.getId(),e.getMessage());}}}}
